#!/usr/bin/env python3
"""Database migration script v2.4.1 - Migrates user preferences from JSON to typed columns.

Handles legacy data where preference values may be stored as strings, integers,
or nested objects depending on the client version that wrote them.
"""

import json
import sqlite3
from flask import Flask, request, render_template_string, jsonify

app = Flask(__name__)
DB_PATH = '/var/lib/app/preferences.db'

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def migrate_preference_value(raw_value, target_type):
    """Migrate a preference value to the target type.

    Legacy data may have type confusion issues where strings contain
    serialized objects or numeric strings that need coercion.
    """
    if target_type == 'integer':
        try:
            return int(raw_value)
        except (ValueError, TypeError):
            return 0
    elif target_type == 'boolean':
        if isinstance(raw_value, str):
            return raw_value.lower() in ('true', '1', 'yes')
        return bool(raw_value)
    elif target_type == 'json_object':
        if isinstance(raw_value, str):
            try:
                return json.loads(raw_value)
            except json.JSONDecodeError:
                return {}
        return raw_value if isinstance(raw_value, dict) else {}
    elif target_type == 'display_html':
        # Type confusion: if value is dict, extract 'content' key
        # if value is string, use directly as display content
        if isinstance(raw_value, dict):
            return raw_value.get('content', '')
        elif isinstance(raw_value, (int, float)):
            return str(raw_value)
        else:
            # String values passed through for HTML display preferences
            return raw_value
    return str(raw_value)

@app.route('/admin/migration/preview')
def preview_migration():
    """Preview migration results for admin review before committing."""
    user_id = request.args.get('user_id', '')
    db = get_db()

    rows = db.execute(
        'SELECT key, value, target_type FROM pending_migrations WHERE user_id = ?',
        (user_id,)
    ).fetchall()

    results = []
    for row in rows:
        raw = row['value']
        # Attempt JSON parse for values that might be serialized
        try:
            parsed = json.loads(raw)
        except (json.JSONDecodeError, TypeError):
            parsed = raw

        migrated = migrate_preference_value(parsed, row['target_type'])
        results.append({
            'key': row['key'],
            'original': raw,
            'migrated': migrated,
            'type': row['target_type']
        })

    # Render preview table for admin
    template = '''<!DOCTYPE html>
<html>
<head><title>Migration Preview</title></head>
<body>
<h1>Migration Preview for User {{ user_id }}</h1>
<table border="1">
<tr><th>Key</th><th>Original</th><th>Migrated Value</th><th>Target Type</th></tr>
{% for r in results %}
<tr>
  <td>{{ r.key }}</td>
  <td>{{ r.original }}</td>
  <td>{{ r.migrated | safe }}</td>
  <td>{{ r.type }}</td>
</tr>
{% endfor %}
</table>
</body>
</html>'''

    return render_template_string(template, user_id=user_id, results=results)

@app.route('/admin/migration/execute', methods=['POST'])
def execute_migration():
    """Execute the migration for a given user."""
    user_id = request.json.get('user_id')
    db = get_db()
    rows = db.execute(
        'SELECT key, value, target_type FROM pending_migrations WHERE user_id = ?',
        (user_id,)
    ).fetchall()

    for row in rows:
        try:
            parsed = json.loads(row['value'])
        except (json.JSONDecodeError, TypeError):
            parsed = row['value']
        migrated = migrate_preference_value(parsed, row['target_type'])
        db.execute(
            'INSERT OR REPLACE INTO user_preferences (user_id, key, value) VALUES (?, ?, ?)',
            (user_id, row['key'], json.dumps(migrated))
        )

    db.execute('DELETE FROM pending_migrations WHERE user_id = ?', (user_id,))
    db.commit()
    return jsonify({'status': 'ok', 'migrated': len(rows)})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
